'use strict';
const fs=require('fs'),path=require('path'),crypto=require('crypto');
const {chromium}=require('playwright');
const BASE=(process.env.P14_BASE_URL||'https://plan-ex.ru/erpv2/').replace(/\/+$/,'/');
const OUT=path.resolve(process.env.P14_OUT_DIR||'P14_output'),SHOTS=path.join(OUT,'P14_tenant_setup_screenshots');
fs.mkdirSync(SHOTS,{recursive:true});
function runtimeCreds(){const e=process.env.P11_CREDENTIALS_B64||'';if(!e)return[];const p=JSON.parse(Buffer.from(e,'base64').toString('utf8'));return Array.isArray(p)?p:[]}
function pick(r){return runtimeCreds().find(x=>String(x?.role||'').toUpperCase()===r)}
function password(){return `P14!${crypto.randomBytes(18).toString('base64url')}aA7`}
function suffix(){const d=new Date();return `${String(d.getUTCFullYear()).slice(-2)}${String(d.getUTCMonth()+1).padStart(2,'0')}${String(d.getUTCDate()).padStart(2,'0')}${String(d.getUTCHours()).padStart(2,'0')}${String(d.getUTCMinutes()).padStart(2,'0')}${String(d.getUTCSeconds()).padStart(2,'0')}`}
function inn10(){const a=('77014'+String(Date.now()).slice(-4)).slice(0,9).split('').map(Number),w=[2,4,10,3,5,9,4,6,8];return a.join('')+((a.reduce((s,x,i)=>s+x*w[i],0)%11)%10)}
async function login(ctx,c){const p=await ctx.newPage();await p.goto(new URL('login',BASE),{waitUntil:'domcontentloaded',timeout:45000});await p.locator('input[name="username"],input[name="email"],input[type="email"],input[type="text"]').first().fill(c.username);await p.locator('input[type="password"]').first().fill(c.password);await Promise.all([p.waitForLoadState('domcontentloaded',{timeout:30000}).catch(()=>{}),p.locator('button[type="submit"],input[type="submit"]').first().click()]);await p.waitForTimeout(800);if(/\/login(?:[/?#]|$)/i.test(p.url()))throw Error('authentication failed');return p}
async function set(form,n,v){const l=form.locator(`[name="${n}"]`).first();if(!(await l.count()))return false;const t=await l.evaluate(e=>e.tagName);if(t==='SELECT')await l.selectOption(String(v));else await l.fill(String(v));return true}
async function submit(page,form){const rp=page.waitForResponse(r=>r.request().method()==='POST',{timeout:20000}).catch(()=>null);await form.evaluate(f=>f.requestSubmit());const r=await rp;await page.waitForLoadState('domcontentloaded',{timeout:20000}).catch(()=>{});await page.waitForTimeout(800);return r}
async function companyId(page,name){await page.goto(new URL('superadmin/companies',BASE),{waitUntil:'domcontentloaded',timeout:45000});const q=page.locator('input[name="search"]').first();if(await q.count()){await q.fill(name);const f=q.locator('xpath=ancestor::form[1]');await f.evaluate(x=>x.requestSubmit());await page.waitForLoadState('domcontentloaded',{timeout:20000}).catch(()=>{});await page.waitForTimeout(500)}const links=await page.locator('a[href*="/superadmin/companies/"]').evaluateAll(ns=>ns.map(n=>({h:n.href,t:(n.textContent||'').trim()})));for(const x of links){if(x.t.includes(name)){const m=x.h.match(/\/superadmin\/companies\/(\d+)/);if(m)return Number(m[1])}}return null}
async function createCompany(page,name,result){let id=await companyId(page,name);if(id){result.companyReused=true;return id}await page.goto(new URL('superadmin/companies/create',BASE),{waitUntil:'domcontentloaded',timeout:45000});const f=page.locator('form[action$="/superadmin/companies/create"]').first();if(!(await f.count()))throw Error('company form unavailable');await set(f,'name',name);await set(f,'inn',inn10());const r=await submit(page,f);result.companyCreateHttpStatus=r?.status()??null;id=await companyId(page,name);if(id)return id;result.companyCreateBodyExcerpt=(await page.locator('body').innerText().catch(()=>'' )).replace(/\s+/g,' ').slice(0,1000);throw Error('company create validation failure')}
async function createOwner(page,id,a){await page.goto(new URL(`superadmin/companies/${id}/owner`,BASE),{waitUntil:'domcontentloaded',timeout:45000});let f=page.locator('form').filter({has:page.locator('[name="full_name"]')}).first();if(!(await f.count())){const b=page.locator('button,a').filter({hasText:/создать.*руковод|добавить.*руковод/i}).first();if(await b.count()){await b.click();await page.waitForTimeout(700);f=page.locator('form').filter({has:page.locator('[name="full_name"]')}).first()}}if(!(await f.count())){await page.goto(new URL(`superadmin/companies/${id}/owner/edit`,BASE),{waitUntil:'domcontentloaded',timeout:45000});f=page.locator('form').filter({has:page.locator('[name="full_name"]')}).first()}if(!(await f.count()))throw Error('owner form unavailable');await set(f,'full_name','Тестов Владелец П14');await set(f,'login',a.username);await set(f,'email',`${a.username}@example.test`);await set(f,'phone','+79990001401');await set(f,'position','Генеральный директор');await set(f,'status','active');await set(f,'comments','P14 isolated test owner');const has=await set(f,'password',a.password);if(!has)throw Error('owner password field unavailable');const r=await submit(page,f);if(r&&r.status()>=400)throw Error('owner create http failure')}
async function createUser(page,id,a,role){await page.goto(new URL(`superadmin/companies/${id}/users`,BASE),{waitUntil:'domcontentloaded',timeout:45000});const b=page.locator('button,a').filter({hasText:/создать пользователя/i}).first();if(!(await b.count()))throw Error('user trigger unavailable');await b.click();await page.waitForTimeout(600);const f=page.locator('#sa-logist-create-form,form[action*="/users/logists/modal-create"]').first();if(!(await f.count()))throw Error('user form unavailable');await set(f,'full_name',a.fullName);await set(f,'login',a.username);await set(f,'email',`${a.username}@example.test`);await set(f,'phone',a.phone);await set(f,'role',role);await set(f,'password',a.password);const r=await submit(page,f);if(r&&r.status()>=400)throw Error('user create http failure')}
async function verify(browser,a,role,result){const c=await browser.newContext({viewport:{width:1920,height:1080},deviceScaleFactor:1,ignoreHTTPSErrors:true,locale:'ru-RU',timezoneId:'Europe/Moscow'});const p=await login(c,{username:a.username,password:a.password});const r=await p.goto(new URL('company/dashboard',BASE),{waitUntil:'domcontentloaded',timeout:45000}).catch(()=>null);await p.waitForTimeout(400);const text=await p.locator('body').innerText().catch(()=>''),pass=r?.status()===200&&!/\/login(?:[/?#]|$)/i.test(p.url())&&!/доступ запрещ|forbidden/i.test(text),shot=`P14_ROLE_${role}_DASHBOARD_1920x1080.png`;await p.screenshot({path:path.join(SHOTS,shot),fullPage:false}).catch(()=>{});result.roleLoginChecks.push({role,httpStatus:r?.status()??null,finalUrl:p.url(),pass,screenshot:shot});await c.close();if(!pass)throw Error(`role login failed ${role}`)}
(async()=>{const result={status:'FAIL',companyName:'UIUX TEST EXPEDITOR',companyId:null,companyReused:false,companyCreateHttpStatus:null,companyCreateBodyExcerpt:null,createdRoles:[],roleLoginChecks:[],screenshots:[],errors:[]};let browser;try{const sa=pick('SUPERADMIN');if(!sa)throw Error('superadmin unavailable');const s=suffix(),owner={username:`p14_owner_${s}`,password:password()},senior={fullName:'Тестов Старший Логист П14',username:`p14_senior_${s}`,password:password(),phone:'+79990001402'},l1={fullName:'Тестов Логист Один П14',username:`p14_logist1_${s}`,password:password(),phone:'+79990001403'},l2={fullName:'Тестов Логист Два П14',username:`p14_logist2_${s}`,password:password(),phone:'+79990001404'};browser=await chromium.launch({headless:true});const c=await browser.newContext({viewport:{width:1920,height:1080},deviceScaleFactor:1,ignoreHTTPSErrors:true,locale:'ru-RU',timezoneId:'Europe/Moscow'}),p=await login(c,{...sa});result.companyId=await createCompany(p,result.companyName,result);await p.goto(new URL(`superadmin/companies/${result.companyId}`,BASE),{waitUntil:'domcontentloaded',timeout:45000});await p.screenshot({path:path.join(SHOTS,'P14_TEST_COMPANY_CREATED_1920x1080.png'),fullPage:false});result.screenshots.push('P14_TEST_COMPANY_CREATED_1920x1080.png');await createOwner(p,result.companyId,owner);result.createdRoles.push('COMPANY_OWNER');await createUser(p,result.companyId,senior,'senior_logist');result.createdRoles.push('SENIOR_LOGIST');await createUser(p,result.companyId,l1,'logist');result.createdRoles.push('LOGIST_1');await createUser(p,result.companyId,l2,'logist');result.createdRoles.push('LOGIST_2');await p.goto(new URL(`superadmin/companies/${result.companyId}/users`,BASE),{waitUntil:'domcontentloaded',timeout:45000});await p.screenshot({path:path.join(SHOTS,'P14_TEST_COMPANY_USERS_1920x1080.png'),fullPage:false});result.screenshots.push('P14_TEST_COMPANY_USERS_1920x1080.png');await c.close();await verify(browser,owner,'COMPANY_OWNER',result);await verify(browser,senior,'SENIOR_LOGIST',result);await verify(browser,l1,'LOGIST_1',result);await verify(browser,l2,'LOGIST_2',result);owner.password=senior.password=l1.password=l2.password='';result.status='PASS'}catch(e){result.errors.push({name:e?.name||'Error',message:String(e?.message||e).replace(/p14_[a-z0-9_]+/gi,'[REDACTED_LOGIN]').slice(0,600)})}finally{if(browser)await browser.close().catch(()=>{});fs.writeFileSync(path.join(OUT,'P14_runtime_result.json'),JSON.stringify(result,null,2));console.log(`P14_TENANT_SETUP=${result.status}`);process.exitCode=result.status==='PASS'?0:1}})().catch(()=>{console.log('P14_TENANT_SETUP=FAIL');process.exitCode=1});
